local TableMaker = {}
local PRODUCTS = {
    simple_oak_table = { name = "Preprosta hrastova miza", woodCost = 4, time = 5, cost = 80, beauty = 22, happiness = 1, description = "Preprosta hrastova miza za hišo." },
    carved_walnut_table = { name = "Izrezljana orehova miza", woodCost = 4, leatherCost = 1, time = 7, cost = 220, beauty = 38, happiness = 2, prestige = 2, description = "Izrezljana orehova miza za trgovce." },
    silver_trimmed_table = { name = "Srebrnoobrobljena miza", woodCost = 4, silverCost = 1, leatherCost = 1, time = 10, cost = 520, beauty = 52, happiness = 2, prestige = 6, description = "Srebrnoobrobljena miza za plemiče." },
    gold_inlaid_table = { name = "Zlatovložena miza", woodCost = 5, goldCost = 1, silverCost = 1, leatherCost = 1, time = 14, cost = 1200, beauty = 65, happiness = 3, prestige = 14, description = "Zlatovložena miza za visoke plemiče." },
    jewel_set_banquet_table = { name = "Draguljasta banketna miza", woodCost = 5, goldCost = 2, silverCost = 1, leatherCost = 1, jewelCost = 1, time = 18, cost = 2700, beauty = 78, happiness = 5, prestige = 27, description = "Banketna miza z draguljem za visoko plemstvo." },
    royal_grand_table = { name = "Kraljevski velika miza", woodCost = 7, goldCost = 3, silverCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 25, cost = 5800, beauty = 92, happiness = 12, prestige = 58, description = "Velika kraljevska miza z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    table_workshop = { name = "Mizarska delavnica", cost = { gold = 260, wood = 180, stone = 100 }, upkeep = 6, qualityBonus = 5 },
    furniture_loft = { name = "Pohištvena podstrešje", cost = { gold = 950, wood = 340, stone = 220, silver = 6 }, upkeep = 22, qualityBonus = 18 },
    master_table_atelier = { name = "Mojstrski mizarski atelje", cost = { gold = 2700, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_table_palace = { name = "Kraljevska mizarska palača", cost = { gold = 11500, wood = 600, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
TableMaker.woodStock = 22; TableMaker.leatherStock = 10; TableMaker.silverStock = 6; TableMaker.goldStock = 6; TableMaker.jewelStock = 4; TableMaker.pearlStock = 4
TableMaker.productStock = {}; TableMaker.buildings = {}; TableMaker.maker = nil; TableMaker.activeMaking = {}; TableMaker.totalProducts = 0; TableMaker.dayTimer = 0
function TableMaker.init() TableMaker.woodStock=22; TableMaker.leatherStock=10; TableMaker.silverStock=6; TableMaker.goldStock=6; TableMaker.jewelStock=4; TableMaker.pearlStock=4; TableMaker.productStock={}; TableMaker.buildings={}; TableMaker.maker=nil; TableMaker.activeMaking={}; TableMaker.totalProducts=0; TableMaker.dayTimer=0; print("[TableMaker] Royal Table Maker System initialized (6 products, 4 buildings)") end
function TableMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TableMaker.maker={name=n or ("Mizar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mizar najet: %s (spretnost: %d)",TableMaker.maker.name,s),"success") end; return true end
function TableMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TableMaker.build(id) local ok,e=TableMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TableMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TableMaker.getQualityBonus() local b=0; for _,bd in ipairs(TableMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TableMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and TableMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and TableMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and TableMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TableMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TableMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TableMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TableMaker.buildings==0 then return false,"Potrebna mizarska delavnica" end; if not TableMaker.maker then return false,"Potreben mizar" end; return true end
function TableMaker.make(pt,qty) qty=qty or 1; local ok,e=TableMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then TableMaker.woodStock=TableMaker.woodStock-d.woodCost*qty end; if d.leatherCost then TableMaker.leatherStock=TableMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then TableMaker.silverStock=TableMaker.silverStock-d.silverCost*qty end; if d.goldCost then TableMaker.goldStock=TableMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TableMaker.jewelStock=TableMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TableMaker.pearlStock=TableMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TableMaker.maker then t=math.max(1,t-math.floor(TableMaker.maker.skill/12)) end; table.insert(TableMaker.activeMaking,{id="table_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TableMaker.completeMaking(m) local q=1.0+(TableMaker.getQualityBonus()/100); if TableMaker.maker then q=q+(TableMaker.maker.skill/140) end; q=math.min(2.5,q); TableMaker.productStock[m.productType]=(TableMaker.productStock[m.productType] or 0)+m.quantity; TableMaker.totalProducts=TableMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TableMaker.maker then TableMaker.maker.itemsMade=TableMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TableMaker.maker.skill=math.min(100,TableMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Miza izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"table.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function TableMaker.update(dt) if not _G.state then return end; TableMaker.dayTimer=TableMaker.dayTimer+dt; if TableMaker.dayTimer>=30 then TableMaker.dayTimer=0; for i=#TableMaker.activeMaking,1,-1 do local m=TableMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TableMaker.completeMaking(m); table.remove(TableMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TableMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TableMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TableMaker.getStats() return {woodStock=TableMaker.woodStock,leatherStock=TableMaker.leatherStock,silverStock=TableMaker.silverStock,goldStock=TableMaker.goldStock,jewelStock=TableMaker.jewelStock,pearlStock=TableMaker.pearlStock,productStock=TableMaker.productStock,numBuildings=#TableMaker.buildings,hasMaker=TableMaker.maker~=nil,makerName=TableMaker.maker and TableMaker.maker.name or "—",makerSkill=TableMaker.maker and TableMaker.maker.skill or 0,activeMaking=#TableMaker.activeMaking,totalProducts=TableMaker.totalProducts} end
return TableMaker
